param(\n    [string]$Rootfs = ""\n)\n\n$ErrorActionPreference = "Stop"\n\nif (-not $Rootfs) {\n    $Rootfs = Join-Path $PSScriptRoot "..\\dist\\windows-wsl\\devstack-wsl-rootfs.tar"\n}\n\n$Rootfs = [System.IO.Path]::GetFullPath($Rootfs)\n\nif (-not (Test-Path $Rootfs)) {\n    throw "Rootfs not found: $Rootfs"\n}\n\n$InstallDir = Join-Path $env:LOCALAPPDATA "DevStack\\wsl"\nNew-Item -ItemType Directory -Force -Path $InstallDir | Out-Null\n\n$distros = (wsl.exe --list --quiet) -replace "`0", ""\n\nif ($distros -contains "DevStack") {\n    Write-Host "DevStack WSL2 distro already exists."\n    exit 0\n}\n\nwsl.exe --import DevStack $InstallDir $Rootfs --version 2\nwsl.exe -d DevStack -u root -- /usr/local/sbin/devstack-start\n\nWrite-Host "Dedicated DevStack WSL2 distro installed."\n